INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 102301, 2, 10046, 401, 24, 24001, 0, 2, 0, "2020/07/31 12:00:00", "アヤネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 102301, 1, 10046, 402, 24, 24002, 0, 2, 2.21, "2020/07/31 12:00:00", "アヤネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 102301, 2, 10046, 403, 24, 24003, 0, 2, 0, "2020/07/31 12:00:00", "アヤネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 192201, 2, 10046, 701, 24, 24004, 0, 1, 1.99, "2020/07/31 12:00:00", "アサヒ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 192201, 1, 10046, 702, 24, 24005, 0, 2, 2.21, "2020/07/31 12:00:00", "アサヒ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 192201, 2, 10046, 703, 24, 24006, 0, 1, 3.33, "2020/07/31 12:00:00", "アサヒ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 192301, 2, 10046, 801, 24, 24007, 0, 2, 0, "2020/07/31 12:00:00", "部員３", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 192301, 1, 10046, 802, 24, 24008, 0, 2, 2.68, "2020/07/31 12:00:00", "部員３", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 192301, 2, 10046, 803, 24, 24009, 0, 2, 0, "2020/07/31 12:00:00", "部員３", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "やった！", 192501, 1, 10046, 501, 24, 24010, 0, 1, 0, "2020/07/31 12:00:00", "", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "勝ったよ！", 192501, 1, 10046, 502, 24, 24011, 0, 1, 0, "2020/07/31 12:00:00", "", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "いい調子！", 192501, 1, 10046, 503, 24, 24012, 0, 1, 0, "2020/07/31 12:00:00", "", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 113501, 6, 10046, 111, 24, 24013, 0, 2, 5.33, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 113501, 1, 10046, 112, 24, 24014, 0, 2, 6.85, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 113501, 1, 10046, 113, 24, 24015, 0, 2, 3, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 192401, 1, 10046, 611, 24, 24016, 0, 2, 6.11, "2020/07/31 12:00:00", "ダイチ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 192401, 1, 10046, 612, 24, 24017, 0, 2, 6.75, "2020/07/31 12:00:00", "ダイチ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 192401, 2, 10046, 613, 24, 24018, 0, 2, 0, "2020/07/31 12:00:00", "ダイチ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 113401, 2, 10046, 211, 24, 24019, 0, 1, 4.52, "2020/07/31 12:00:00", "ハツネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 113401, 2, 10046, 212, 24, 24020, 0, 1, 3.89, "2020/07/31 12:00:00", "ハツネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 113401, 1, 10046, 213, 24, 24021, 0, 2, 13.49, "2020/07/31 12:00:00", "ハツネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 106501, 1, 10046, 311, 24, 24022, 0, 2, 3.17, "2020/07/31 12:00:00", "カヤ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 106501, 1, 10046, 312, 24, 24023, 0, 2, 4.42, "2020/07/31 12:00:00", "カヤ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 106501, 6, 10046, 313, 24, 24024, 0, 1, 2.89, "2020/07/31 12:00:00", "カヤ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 102301, 4, 10046, 421, 24, 24025, 0, 3, 3.71, "2020/07/31 12:00:00", "アヤネ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 192201, 2, 10046, 721, 24, 24026, 0, 1, 5.1, "2020/07/31 12:00:00", "アサヒ", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 192301, 1, 10046, 821, 24, 24027, 0, 3, 4.34, "2020/07/31 12:00:00", "部員３", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (0, "いい勝負だったよ\nまたやろうね", 192501, 1, 10046, 521, 24, 24028, 0, 1, 0, "2020/07/31 12:00:00", "", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (-360, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 113501, 1, 10046, 101, 24, 24029, 0, 2, 5.62, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (-360, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 113501, 1, 10046, 102, 24, 24030, 0, 2, 9.58, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (-360, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 113501, 2, 10046, 103, 24, 24031, 0, 2, 0, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (-360, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 113501, 2, 10046, 104, 24, 24032, 0, 1, 9.13, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (-360, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 113501, 1, 10046, 105, 24, 24033, 0, 2, 8.27, "2020/07/31 12:00:00", "ミサト", "2030/12/17 14:59:59");
